17	package org.apache.kafka.streams.kstream.internals;
18	
19	import org.apache.kafka.common.utils.Bytes;
20	import org.apache.kafka.streams.DslStoreFormat;
21	import org.apache.kafka.streams.kstream.EmitStrategy;
22	import org.apache.kafka.streams.kstream.SessionWindows;
23	import org.apache.kafka.streams.state.DslSessionParams;
24	import org.apache.kafka.streams.state.SessionBytesStoreSupplier;
25	import org.apache.kafka.streams.state.SessionStore;
26	import org.apache.kafka.streams.state.SessionStoreWithHeaders;
27	import org.apache.kafka.streams.state.StoreBuilder;
28	import org.apache.kafka.streams.state.Stores;
29	
30	import java.time.Duration;
31	
32	public class SessionStoreMaterializer<K, V> extends MaterializedStoreFactory<K, V, SessionStore<Bytes, byte[]>> {
33	
34	    private final MaterializedInternal<K, V, SessionStore<Bytes, byte[]>> materialized;
35	    private final SessionWindows sessionWindows;
36	    private final EmitStrategy emitStrategy;
37	    private final long retentionPeriod;
38	
39	    public SessionStoreMaterializer(
40	            final MaterializedInternal<K, V, SessionStore<Bytes, byte[]>> materialized,
41	            final SessionWindows sessionWindows,
42	            final EmitStrategy emitStrategy
43	    ) {
44	        super(materialized, DslStoreFormat.PLAIN);
45	        this.materialized = materialized;
46	        this.sessionWindows = sessionWindows;
47	        this.emitStrategy = emitStrategy;
48	
49	        retentionPeriod = retentionPeriod();
50	        if ((sessionWindows.inactivityGap() + sessionWindows.gracePeriodMs()) > retentionPeriod) {
51	            throw new IllegalArgumentException("The retention period of the session store "
52	                    + materialized.storeName()
53	                    + " must be no smaller than the session inactivity gap plus the"
54	                    + " grace period."
55	                    + " Got gap=[" + sessionWindows.inactivityGap() + "],"
56	                    + " grace=[" + sessionWindows.gracePeriodMs() + "],"
57	                    + " retention=[" + retentionPeriod + "]");
58	        }
59	    }
60	
61	    @Override
62	    public  StoreBuilder<SessionStoreWithHeaders<K, V>> builder() {
63	        final SessionBytesStoreSupplier supplier = materialized.storeSupplier() == null
64	                ? dslStoreSuppliers().sessionStore(new DslSessionParams(
65	                        materialized.storeName(),
66	                        Duration.ofMillis(retentionPeriod),
67	                        emitStrategy,
68	                        dslStoreFormat()))
69	                : (SessionBytesStoreSupplier) materialized.storeSupplier();
70	
71	        final StoreBuilder<SessionStoreWithHeaders<K, V>> builder = Stores.sessionStoreBuilderWithHeaders(
72	                    supplier,
73	                    materialized.keySerde(),
74	                    materialized.valueSerde()
75	            );
76	
77	        if (materialized.loggingEnabled()) {
78	            builder.withLoggingEnabled(materialized.logConfig());
79	        } else {
80	            builder.withLoggingDisabled();
81	        }
82	
83	        // do not enable cache if the emit final strategy is used
84	        if (materialized.cachingEnabled() && emitStrategy.type() != EmitStrategy.StrategyType.ON_WINDOW_CLOSE) {
85	            builder.withCachingEnabled();
86	        } else {
87	            builder.withCachingDisabled();
88	        }
89	
90	        return builder;
91	    }
92	
93	    @Override
94	    public final long retentionPeriod() {
95	        return materialized.retention() != null
96	                ? materialized.retention().toMillis()
97	                : sessionWindows.inactivityGap() + sessionWindows.gracePeriodMs();
98	    }
99	
100	    @Override
101	    public long historyRetention() {
102	        throw new IllegalStateException(
103	                "historyRetention is not supported when not a versioned store");
104	    }
105	
106	    @Override
107	    public boolean isWindowStore() {
108	        return true;
109	    }
110	
111	    @Override
112	    public boolean isVersionedStore() {
113	        return false;
114	    }
115	
116	}
