22	
23	public class RocksDbTimeOrderedSessionBytesStoreSupplier implements SessionBytesStoreSupplier {
24	    private final String name;
25	    private final long retentionPeriod;
26	    private final boolean withIndex;
27	    private final boolean withHeaders;
28	
29	    public RocksDbTimeOrderedSessionBytesStoreSupplier(final String name,
30	                                                       final long retentionPeriod,
31	                                                       final boolean withIndex) {
32	        this(name, retentionPeriod, withIndex, false);
33	    }
34	
35	    public RocksDbTimeOrderedSessionBytesStoreSupplier(final String name,
36	                                                       final long retentionPeriod,
37	                                                       final boolean withIndex,
38	                                                       final boolean withHeaders) {
39	        this.name = name;
40	        this.retentionPeriod = retentionPeriod;
41	        this.withIndex = withIndex;
42	        this.withHeaders = withHeaders;
43	    }
44	
45	    @Override
46	    public String name() {
47	        return name;
48	    }
49	
50	    @Override
51	    public SessionStore<Bytes, byte[]> get() {
52	        if (withHeaders) {
53	            final RocksDBTimeOrderedSessionSegmentedBytesStoreWithHeaders bytesStore =
54	                new RocksDBTimeOrderedSessionSegmentedBytesStoreWithHeaders(
55	                    name,
56	                    metricsScope(),
57	                    retentionPeriod,
58	                    segmentIntervalMs(),
59	                    withIndex
60	                );
61	            return new RocksDBTimeOrderedSessionStore(bytesStore);
62	        }
63	        final RocksDBTimeOrderedSessionSegmentedBytesStore<KeyValueSegment> bytesStore =
64	            new RocksDBTimeOrderedSessionSegmentedBytesStore<>(
65	                name,
66	                retentionPeriod,
67	                withIndex,
68	                new KeyValueSegments(name, metricsScope(), retentionPeriod, segmentIntervalMs())
69	            );
70	        return new RocksDBTimeOrderedSessionStore(bytesStore);
71	    }
72	
73	    @Override
74	    public String metricsScope() {
75	        return "rocksdb-session";
76	    }
77	
78	    @Override
79	    public long segmentIntervalMs() {
80	        // Selected somewhat arbitrarily. Profiling may reveal a different value is preferable.
81	        return Math.max(retentionPeriod / 2, 60_000L);
82	    }
83	
84	    @Override
85	    public long retentionPeriod() {
86	        return retentionPeriod;
87	    }
88	}
